    if _is_empty(value):
        return Decimal(0)
    if isinstance(value, bool):
        return Decimal(int(value))
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal(0)


def _qualify_guard(record: dict) -> bool:
    return _numeric_value(record.get("AMT", "")) > Decimal(0)


def _close_won_guard(record: dict) -> bool:
    value = record.get("CLOSE_DT", "")
    if _is_empty(value):
        value = ""
    return str(value) != "00000000"


def _close_lost_guard(record: dict) -> bool:
    value = record.get("LOST_RSN", "")
    return not _is_empty(value) and str(value) != ""


_TRANSITIONS = (
    ("P", "Q", "qualify", _qualify_guard, (("set", "STAGE_PCT", "25"), ("audit", "OPP_QUAL"))),
    ("Q", "N", "advance", None, (("set", "STAGE_PCT", "60"),)),
    (
        "N",
        "W",
        "close_won",
        _close_won_guard,
        (("set", "STAGE_PCT", "100"), ("audit", "OPP_WON"), ("notify", "won_deal")),
    ),
    (
        "P",
        "L",
        "close_lost",
        _close_lost_guard,
        (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST")),
    ),
    (
        "Q",
        "L",
        "close_lost",
        _close_lost_guard,
        (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST")),
    ),
    (
        "N",
        "L",
        "close_lost",
        _close_lost_guard,
        (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST")),
    ),
)


def fire(state: str, event: str, record: dict) -> dict:
    """Fire the first matching opportunity workflow transition."""
    result_record = dict(record)

    for from_state, to_state, transition_event, guard, actions in _TRANSITIONS:
        if state != from_state or event != transition_event:
            continue
        if guard is not None and not guard(record):
            continue

        audits = []
        notifies = []
        for action in actions:
            if action[0] == "set":
                _, field, value = action
                result_record[field] = value
            elif action[0] == "audit":
                audits.append(action[1])
            elif action[0] == "notify":
                notifies.append(action[1])

        return {
            "state": to_state,
            "record": result_record,
            "audits": audits,
            "notifies": notifies,
            "matched": True,
        }

    return {
        "state": state,
        "record": result_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
